fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

data class Pair200<A, B>(val first: A, val second: B)

fun combine200(left: Int, right: Int): Pair200<Int, Int> {
    return Pair200(left + 71, right + 27)
}
fun <T> List<T>.secondOrNull201(): T? = if (size > 1) this[1] else null

fun render201(values: List<String>?): String {
    return values?.filter { it.isNotBlank() }?.joinToString(separator = ",") ?: "empty"
}
class Counter202 {
    var current: Int by Delegates.observable(85) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
